  for(const q of samples)for(const [o,dz] of prof)push(q,o,dz);
  for(let i=0;i<m-1;i++)for(let k=0;k<4;k++){const a=i*4+k,b=i*4+(k+1)%4,c=(i+1)*4+k,d=(i+1)*4+(k+1)%4;idx.push(a,c,b,b,c,d);}
  for(const i of [0,m-1]){const b=i*4;idx.push(b,b+1,b+2,b,b+2,b+3);}
