function treads(fn,a0,a1,z0,z1,w){const steps=Math.max(4,Math.round(Math.abs(z1-z0)/.167));const pos=[];for(let i=1;i<steps;i++){const t=i/steps,a=a0+(a1-a0)*t,z=z0+(z1-z0)*t+.01,q=fn(a);pos.push(q.p[0]+q.n[0]*w,z,-(q.p[1]+q.n[1]*w),q.p[0]-q.n[0]*w,z,-(q.p[1]-q.n[1]*w));}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));return g;}
function sector(c,r0,r1,b0,b1){const A=[],B=[];const n=Math.ceil((b1-b0)/2);for(let i=0;i<=n;i++){const b=(b0+(b1-b0)*i/n)*deg;A.push([c[0]+r1*Math.cos(b),c[1]+r1*Math.sin(b)]);B.push([c[0]+r0*Math.cos(b),c[1]+r0*Math.sin(b)]);}return A.concat(B.reverse());}
